    """Find prime factors of a number."""
    factors = set()
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            factors.add(i)
            n //= i
    if n > 1:
        factors.add(n)
    return factors

def max_value(d):
    """Compute maximum value for each key in dictionary."""
    max_val = 0
    for key, value in d.items():
        if isinstance(value, int) and value % 3 == 0:
            factors = prime_factors(value)
            if any(is_prime(factor) for factor in factors):
                max_val = max(max_val, value)
    return max_val

# Example usage:
d = {'a': 12, 'b': 20, 'c': 30}
print(max_value(d))  # Output: 30
```

