### Cleaning JSON Data for Consistent Data Types

To clean the JSON data and ensure all fields have the same data type, we will use a recursive approach to handle nested objects and arrays of arbitrary depth. We will also convert the `age` field to a string data type.

#### JSON Data Example

```json
{
    "firstname": "John",
    "lastname": "Doe",
    "age": 30,
    "hobbies": [
        "reading",
        "swimming",
        null,
        {
            "name": "gaming",
            "level": "expert"
        }
    ],
    "address": {
        "street": "123 Main St",
        "city": "New York",
        "state": "NY"
    }
}
```

#### Solution

```python
import json

def clean_json_data(data):
    """
    Recursively cleans the JSON data to ensure all fields have the same data type.
    Converts the 'age' field to a string data type.
    Handles nested JSON objects and arrays of arbitrary depth.
    Preserves the original structure of the JSON data.
    """
    if isinstance(data, dict):
        # If the data is a dictionary, iterate over its items
        cleaned_data = {}
        for key, value in data.items():
            # If the key is 'age', convert its value to a string
            if key == 'age':
                cleaned_data[key] = str(value)
            # If the value is a dictionary or a list, recursively clean it
            elif isinstance(value, (dict, list)):
                cleaned_data[key] = clean_json_data(value)
            # If the value is None, replace it with an empty string
            elif value is None:
                cleaned_data[key] = ''
            # Otherwise, convert the value to a string
            else:
                cleaned_data[key] = str(value)
        return cleaned_data
    elif isinstance(data, list):
        # If the data is a list, iterate over its elements
        cleaned_data = []
        for element in data:
            # If the element is a dictionary or a list, recursively clean it
            if isinstance(element, (dict, list)):
                cleaned_data.append(clean_json_data(element))
            # If the element is None, replace it with an empty string
            elif element is None:
                cleaned_data.append('')
            # Otherwise, convert the element to a string
            else:
                cleaned_data.append(str(element))
        return cleaned_data
    else:
        # If the data is not a dictionary or a list, convert it to a string
        return str(data)

# Example usage
json_data = '''
{
    "firstname": "John",
    "lastname": "Doe",
    "age": 30,
    "hobbies": [
        "reading",
        "swimming",
        null,
        {
            "name": "gaming",
            "level": "expert"
        }
    ],
    "address": {
        "street": "123 Main St",
        "city": "New York",
        "state": "NY"
    }
}
'''

data = json.loads(json_data)
cleaned_data = clean_json_data(data)
print(json.dumps(cleaned_data, indent=4))
```

