            raise ValueError("Invalid street name. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return street_name

    def _validate_house_number(self, house_number):
        if not house_number or not re.match("^[a-zA-Z0-9 ]+$", house_number) or len(house_number) > 50:
            raise ValueError("Invalid house number. It should not be empty, contain only letters, numbers, and spaces, and not exceed 50 characters.")
        return house_number

    def _validate_city(self, city):
        if not city or not re.match("^[a-zA-Z ]+$", city) or len(city) > 50:
            raise ValueError("Invalid city. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return city

    def _validate_state(self, state):
        if not state or not re.match("^[a-zA-Z ]+$", state) or len(state) > 50:
            raise ValueError("Invalid state. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return state

    def _validate_zip_code(self, zip_code):
        if not zip_code or not re.match("^\d{5}$", zip_code):
            raise ValueError("Invalid zip code. It should be a 5-digit number.")
        return zip_code

    def get_full_address(self):
        return f"{self.street_name}, {self.house_number}, {self.city}, {self.state}, {self.zip_code}"


