        return self.age * 12

    def get_birth_year(self):
        current_year = datetime.now().year
        return current_year - self.age

    def add_address(self, address):
        if len(self.addresses) < self.max_addresses:
            self.addresses.append(address)
        else:
            raise ValueError("Maximum number of addresses reached.")

    def remove_address(self, address):
        if address in self.addresses:
            self.addresses.remove(address)
        else:
            raise ValueError("Address not found.")

    def get_address(self, index):
        if index < len(self.addresses):
            return self.addresses[index]
        else:
            raise ValueError("Address not found.")

    def search_hobby(self, hobby):
        for h in self.hobbies:
            if hobby.lower() in h.lower():
                return True
        return False

    def display_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age}")
        print(f"Hobbies: {', '.join(self.hobbies)}")
        for i, address in enumerate(self.addresses):
            print(f"Address {i+1}: {address.get_full_address()}")


