    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n**0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def delete_items(lst):
    new_lst = []
    for item in lst:
        if item % 3 == 0 and item % 5 == 0 and item > 10:
            continue
        if is_prime(item):
            continue
        new_lst.append(item)
    return new_lst

