from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

login_manager = LoginManager()

class User(UserMixin):
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

def task_func(secret_key, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key
    login_manager.init_app(app)
    login_manager.login_view = 'login'

    users = {}

    @login_manager.user_loader
    def load_user(user_id):
        return users.get(int(user_id))

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            username = form.username.data
            password = form.password.data
            user = users.get(username)
            if user and user.check_password(password):
                login_user(user)
                return redirect(url_for('protected'))
            else:
                return render_template('login.html', form=form, error='Invalid username or password')
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return render_template('protected.html', username=current_user.username)

    # Create a test user
    users['test'] = User(1, 'test', 'password123')

    return app

# Example usage
if __name__ == '__main__':
    app = task_func('secret_key', 'templates')
    app.run(debug=True)
```

### Explanation

This code creates a Flask application with user authentication using Flask-Login and Flask-WTF. The `task_func` function initializes the application with a secret key and template folder. It defines a `User` class to manage user data and a `LoginForm` to handle user input.

The application uses a dictionary to store user data, with usernames as keys and `User` objects as values. The `load_user` function is used by Flask-Login to retrieve a user by their ID.

The `/login` route handles both GET and POST requests. When a user submits the login form, it checks the username and password against the stored user data. If the credentials are valid, it logs the user in and redirects them to the protected page. Otherwise, it displays an error message.

The `/logout` route logs the user out and redirects them to the login page. The `/protected` route is only accessible to logged-in users and displays a greeting with the username.

The example usage at the end creates an application instance with a secret key and template folder, and runs it in debug mode.

