        """Test the function with a DataFrame that has no titles containing 'like' or 'what'."""
        data = {
            'Title': [
                'Understanding AI',
                'Introduction to Machine Learning'
            ],
            'Content': [
                'AI is a broad field.',
                'Machine learning is a subset of AI.'
            ]
        }
