from rest_framework import status
from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.pagination import PageNumberPagination
from elasticsearch import Elasticsearch
from elasticsearch.exceptions import ConnectionError
from .models import SignalDocument, StatusMessagesSearch
from .serializers import SignalDocumentSerializer, StatusMessagesSearchSerializer
from .permissions import IsMunicipalUser

class StandardResultsSetPagination(PageNumberPagination):
    page_size = 10
    page_size_query_param = 'page_size'
    max_page_size = 100

class SearchSignalsView(APIView):
    permission_classes = [IsAuthenticated, IsMunicipalUser]
    pagination_class = StandardResultsSetPagination

    def get(self, request):
        search_term = request.GET.get('search_term')
        page = request.GET.get('page', 1)
        page_size = request.GET.get('page_size', 10)

        try:
            es = Elasticsearch()
            query = {
                'query': {
                    'match': {
                        'text': search_term
                    }
                },
                'sort': [
                    {'created_at': {'order': 'desc'}}
                ]
            }
            response = es.search(index='signals', body=query, from_=(page-1)*page_size, size=page_size)
            results = [SignalDocumentSerializer(signal).data for signal in response['hits']['hits']]
            return Response(results, status=status.HTTP_200_OK)
        except ConnectionError:
            return Response({'error': 'Elasticsearch service is unavailable'}, status=status.HTTP_503_SERVICE_UNAVAILABLE)

class SearchStatusMessagesView(APIView):
    permission_classes = [IsAuthenticated, IsMunicipalUser]
    pagination_class = StandardResultsSetPagination

    def get(self, request):
        search_term = request.GET.get('search_term')
        state = request.GET.get('state')
        active = request.GET.get('active')
        page = request.GET.get('page', 1)
        page_size = request.GET.get('page_size', 10)

        try:
            es = Elasticsearch()
            query = {
                'query': {
                    'bool': {
                        'must': [
                            {'match': {'text': search_term}},
                            {'term': {'state': state}} if state else {},
                            {'term': {'active': active}} if active else {}
                        ]
                    }
                },
                'sort': [
                    {'created_at': {'order': 'desc'}}
                ]
            }
            response = es.search(index='status_messages', body=query, from_=(page-1)*page_size, size=page_size)
            results = [StatusMessagesSearchSerializer(message).data for message in response['hits']['hits']]
            return Response(results, status=status.HTTP_200_OK)
        except ConnectionError:
            return Response({'error': 'Elasticsearch service is unavailable'}, status=status.HTTP_503_SERVICE_UNAVAILABLE)
        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_400_BAD_REQUEST)
