class MassEditingSystem:
    def __init__(self):
        self.templates = {}
        self.sidebar_actions = {}

    def create_template(self, name, model):
        if name in self.templates:
            raise ValueError("Template name already exists")
        self.templates[name] = {"model": model, "editing_lines": []}

    def add_editing_line(self, template_name, field, new_value):
        if template_name not in self.templates:
            raise KeyError("Template does not exist")
        self.templates[template_name]["editing_lines"].append((field, new_value))

    def create_sidebar_action(self, template_name):
        if template_name not in self.templates:
            raise KeyError("Template does not exist")
        if template_name in self.sidebar_actions:
            raise KeyError("Sidebar action already exists")
        self.sidebar_actions[template_name] = self.templates[template_name]

    def delete_sidebar_action(self, template_name):
        if template_name not in self.sidebar_actions:
            raise KeyError("Sidebar action does not exist")
        del self.sidebar_actions[template_name]

    def delete_template(self, template_name):
        if template_name not in self.templates:
            raise KeyError("Template does not exist")
        if template_name in self.sidebar_actions:
            del self.sidebar_actions[template_name]
        del self.templates[template_name]

    def copy_template(self, template_name):
        if template_name not in self.templates:
            raise KeyError("Template does not exist")
        new_name = f"Copy of {template_name}"
        if new_name in self.templates:
            raise ValueError("Template name already exists")
        self.templates[new_name] = self.templates[template_name].copy()
        self.templates[new_name]["editing_lines"] = self.templates[template_name]["editing_lines"].copy()

def main():
    system = MassEditingSystem()
    system.create_template("template1", "model1")
    system.add_editing_line("template1", "field1", "new_value1")
    system.create_sidebar_action("template1")
    system.copy_template("template1")
    system.delete_sidebar_action("template1")
    system.delete_template("template1")

if __name__ == "__main__":
    main()
```

