from flask_sqlalchemy import SQLAlchemy
from flask_mail import Mail, Message

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///user_database.db'
app.config['MAIL_SERVER'] = 'smtp.gmail.com'
app.config['MAIL_PORT'] = 465
app.config['MAIL_USE_TLS'] = False
app.config['MAIL_USE_SSL'] = True
app.config['MAIL_USERNAME'] = 'your_email@gmail.com'
app.config['MAIL_PASSWORD'] = 'your_email_password'

db = SQLAlchemy(app)
mail = Mail(app)
login_manager = LoginManager(app)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)
    profile_picture = db.Column(db.String(120), nullable=True)
    ratings = db.relationship('Rating', backref='user', lazy=True)

    def __repr__(self):
        return f"User('{self.username}', '{self.email}')"

class Rating(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    rating = db.Column(db.Integer, nullable=False)

    def __repr__(self):
        return f"Rating('{self.user_id}', '{self.rating}')"

class AccountPublicView:
    def __init__(self, user_id):
        self.user_id = user_id

    def get_public_details(self):
        user = User.query.get(self.user_id)
        if user:
            return {'username': user.username, 'email': user.email}
        else:
            return None

class ChangePasswordView:
    def __init__(self, user_id):
        self.user_id = user_id

    def change_password(self, old_password, new_password):
        user = User.query.get(self.user_id)
        if user and check_password_hash(user.password, old_password):
            user.password = generate_password_hash(new_password)
            db.session.commit()
            return True
        else:
            return False

class Login:
    def __init__(self, email, password):
        self.email = email
        self.password = password

    def login(self):
        user = User.query.filter_by(email=self.email).first()
        if user and check_password_hash(user.password, self.password):
            login_user(user)
            return True
        else:
            return False

class Logout:
    def logout(self):
        logout_user()
        return True

class RegistrationView:
    def __init__(self, username, email, password):
        self.username = username
        self.email = email
        self.password = password

    def register(self):
        user = User.query.filter_by(email=self.email).first()
        if not user:
            new_user = User(username=self.username, email=self.email, password=generate_password_hash(self.password))
            db.session.add(new_user)
            db.session.commit()
            return True
        else:
            return False

class AccountPropertiesView:
    def __init__(self, user_id):
        self.user_id = user_id

    def get_account_properties(self):
        user = User.query.get(self.user_id)
        if user:
            return {'username': user.username, 'email': user.email}
        else:
            return None

    def update_account_properties(self, username, email):
        user = User.query.get(self.user_id)
        if user:
            user.username = username
            user.email = email
            db.session.commit()
            return True
        else:
            return False

class UpdateAccountPicture:
    def __init__(self, user_id):
        self.user_id = user_id

    def update_picture(self, picture):
        user = User.query.get(self.user_id)
        if user:
            user.profile_picture = picture
            db.session.commit()
            return True
        else:
            return False

class VerifyEmail:
    def __init__(self, user_id):
        self.user_id = user_id

    def send_verification_email(self):
        user = User.query.get(self.user_id)
        if user:
            msg = Message('Email Verification', sender='your_email@gmail.com', recipients=[user.email])
            msg.body = 'Your email has been verified.'
            mail.send(msg)
            return True
        else:
            return False

class RatingView:
    def __init__(self, user_id):
        self.user_id = user_id

    def get_ratings(self):
        user = User.query.get(self.user_id)
        if user:
            return [rating.rating for rating in user.ratings]
        else:
            return None

class PostRatingView:
    def __init__(self, user_id):
        self.user_id = user_id

    def post_rating(self, rating):
        user = User.query.get(self.user_id)
        if user:
            new_rating = Rating(user_id=user.id, rating=rating)
            db.session.add(new_rating)
            db.session.commit()
            return True
        else:
            return False

class LoggedInRatingView:
    def __init__(self):
        pass

    def get_ratings(self):
        if current_user.is_authenticated:
            return [rating.rating for rating in current_user.ratings]
        else:
            return None

    def post_rating(self, rating):
        if current_user.is_authenticated:
            new_rating = Rating(user_id=current_user.id, rating=rating)
            db.session.add(new_rating)
            db.session.commit()
            return True
        else:
            return False

# Test cases
def test_user_account_management():
    # Create a new user
    registration_view = RegistrationView('test_user', 'test@example.com', 'password')
    assert registration_view.register()

    # Login the user
