    account_properties_view = AccountPropertiesView(1)
    assert account_properties_view.get_account_properties() == {'username': 'test_user', 'email': 'test@example.com'}

    # Update account properties
    assert account_properties_view.update_account_properties('new_username', 'new_email@example.com')

