```
import os
import requests
from bs4 import BeautifulSoup
import time
import sys

# Constants
URL = "http://srtm.csi.cgiar.org/SELECTION/inputCoord.asp"
DATA_TYPES = ["GeoTIFF", "ASCII"]
OUTPUT_DIR = "srtm_data"

def get_tile_list(data_type):
    response = requests.get(URL)
    soup = BeautifulSoup(response.content, "html.parser")
    tile_list = []
    for link in soup.find_all("a"):
        href = link.get("href")
        if href and href.endswith(data_type.lower() + ".zip"):
            tile_list.append(href.split("/")[-1])
    return tile_list

def download_tile(tile, data_type, output_dir):
    url = f"{URL}/{tile}"
    response = requests.get(url, stream=True)
    if response.status_code == 200:
        with open(os.path.join(output_dir, tile), "wb") as f:
            for chunk in response.iter_content(1024):
                f.write(chunk)
        print(f"Downloaded {tile} successfully")
    else:
        print(f"Failed to download {tile}")

def download_all_tiles(data_type, output_dir):
    tile_list = get_tile_list(data_type)
    for tile in tile_list:
        try:
            download_tile(tile, data_type, output_dir)
        except requests.RequestException as e:
            print(f"Error downloading {tile}: {e}")
            time.sleep(1)
            download_tile(tile, data_type, output_dir)

def main():
    if not os.path.exists(OUTPUT_DIR):
        os.makedirs(OUTPUT_DIR)
    data_type = input("Enter data type (GeoTIFF or ASCII): ")
    if data_type not in DATA_TYPES:
        print("Invalid data type. Exiting.")
        sys.exit(1)
    tile = input("Enter specific tile to download (or press Enter to download all): ")
    if tile:
        download_tile(tile, data_type, OUTPUT_DIR)
    else:
        download_all_tiles(data_type, OUTPUT_DIR)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nDownload cancelled by user. Exiting.")
        sys.exit(0)
```
Note that I've used the `requests` library to make HTTP requests, and `BeautifulSoup` to parse the HTML response from the CGIAR-CSI SRTM data repository. I've also used the `time` library to implement a 1-second delay between retries in case of request exceptions.

The script defines the four functions as specified: `get_tile_list`, `download_tile`, `download_all_tiles`, and `main`. The `main` function handles user input, creates the output directory if it doesn't exist, and calls the `download_tile` or `download_all_tiles` function depending on the user's input.

The script also includes a `try`-`except` block to catch `KeyboardInterrupt` exceptions, which allows the user to cancel the download process with a keyboard interrupt (Ctrl+C). If a `KeyboardInterrupt` exception is caught, the script prints a message indicating that the download was cancelled by the user and exits with a status code of 0.

