def get_primes(n):
    """Generate a list of prime numbers up to a given limit n using the Sieve of Eratosthenes algorithm."""
    sieve = [True] * (n + 1)
    sieve[0:2] = [False, False]  # 0 and 1 are not prime numbers
    for current_prime in range(2, int(n**0.5) + 1):
        if sieve[current_prime]:
            for multiple in range(current_prime*2, n + 1, current_prime):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def min_elements_to_remove(data):
    """Determine the minimum number of elements to remove from a list of integers so that the sum of the remaining elements is a prime number."""
    primes = get_primes(sum(data) + 1)  # Generate prime numbers up to the sum of the list
    min_removals = float('inf')
    removals = []

    # Iterate over all possible subsets of the list
    for mask in range(1 << len(data)):
        subset_sum = sum([data[i] for i in range(len(data)) if (mask & (1 << i)) == 0])
        if subset_sum in primes:
            num_removals = bin(mask).count('1')
            if num_removals < min_removals:
                min_removals = num_removals
                removals = [i + 1 for i in range(len(data)) if (mask & (1 << i)) != 0]

    if min_removals == float('inf'):
        return (-1, [])
    else:
        return (min_removals, removals)

import unittest

class TestMinElementsToRemove(unittest.TestCase):
    def test_already_prime(self):
        self.assertEqual(min_elements_to_remove([2, 3, 5]), (0, []))

