        self.assertEqual(min_elements_to_remove([4, 4, 4]), (-1, []))

    def test_min_removals(self):
        self.assertEqual(min_elements_to_remove([1, 2, 3, 4]), (1, [4]))

    def test_all_even(self):
        self.assertEqual(min_elements_to_remove([2, 4, 6, 8]), (-1, []))

    def test_all_odd(self):
        self.assertEqual(min_elements_to_remove([1, 3, 5, 7]), (0, []))

if __name__ == '__main__':
    unittest.main()
