import requests
from requests.auth import HTTPBasicAuth
from requests.exceptions import RequestException

class JenkinsAPIException(Exception):
    pass

class JenkinsRequester:
    def __init__(self, username=None, password=None, ssl_verify=True):
        self.username = username
        self.password = password
        self.ssl_verify = ssl_verify

    def get_request_dict(self, url, params, data, headers):
        request_dict = {
            'url': url,
            'params': params,
            'data': data,
            'headers': headers,
            'auth': None,
            'verify': self.ssl_verify
        }
        if self.username and self.password:
            request_dict['auth'] = HTTPBasicAuth(self.username, self.password)
        return request_dict

    def get_url(self, url, params=None, headers=None):
        request_dict = self.get_request_dict(url, params, None, headers)
        try:
            response = requests.get(**request_dict)
            response.raise_for_status()
            return response
        except RequestException as e:
            raise JenkinsAPIException(f"Request to {url} failed: {e}")

    def post_url(self, url, params=None, data=None, headers=None):
        request_dict = self.get_request_dict(url, params, data, headers)
        try:
            response = requests.post(**request_dict)
            response.raise_for_status()
            return response
        except RequestException as e:
            raise JenkinsAPIException(f"Request to {url} failed: {e}")

    def post_xml_and_confirm_status(self, url, params=None, data=None, valid=None):
        if data is not None and not isinstance(data, str):
            raise JenkinsAPIException("Data must be a string for XML posts")
        headers = {'Content-Type': 'application/xml'}
        return self.post_and_confirm_status(url, params, data, headers, valid)

    def post_and_confirm_status(self, url, params=None, data=None, headers=None, valid=None):
        if data is not None and not isinstance(data, (str, dict)):
            raise JenkinsAPIException("Data must be a string or a dictionary")
        response = self.post_url(url, params, data, headers)
        self.confirm_status(response, valid)
        return response

    def get_and_confirm_status(self, url, params=None, headers=None, valid=None):
        response = self.get_url(url, params, headers)
        self.confirm_status(response, valid)
        return response

    def confirm_status(self, response, valid=None):
        if valid is None:
            valid = [200]
        if response.status_code not in valid:
            raise JenkinsAPIException(f"Invalid status code {response.status_code} for {response.url}")
