class MetadataFormatType:
    def __init__(self, prefix, schema, namespace):
        self.prefix = prefix
        self.schema = schema
        self.namespace = namespace

class ListMetadataFormatsType:
    def __init__(self):
        self.formats = []

    def add_format(self, format):
        if not isinstance(format, MetadataFormatType):
            raise ValueError("Invalid format type")
        self.formats.append(format)

    def get_formats(self):
        return self.formats

    def find_format(self, prefix):
        if not prefix:
            return None
        for format in self.formats:
            if format.prefix == prefix:
                return format
        return None

# Unit tests
import unittest

class TestMetadataFormats(unittest.TestCase):
    def test_empty_list(self):
        list_metadata_formats = ListMetadataFormatsType()
        self.assertEqual(list_metadata_formats.get_formats(), [])

    def test_add_format(self):
        list_metadata_formats = ListMetadataFormatsType()
        format = MetadataFormatType("prefix", "schema", "namespace")
        list_metadata_formats.add_format(format)
        self.assertEqual(len(list_metadata_formats.get_formats()), 1)

    def test_add_duplicate_format(self):
        list_metadata_formats = ListMetadataFormatsType()
        format1 = MetadataFormatType("prefix", "schema", "namespace")
        format2 = MetadataFormatType("prefix", "schema", "namespace")
        list_metadata_formats.add_format(format1)
        list_metadata_formats.add_format(format2)
        self.assertEqual(len(list_metadata_formats.get_formats()), 2)

    def test_find_format(self):
        list_metadata_formats = ListMetadataFormatsType()
        format = MetadataFormatType("prefix", "schema", "namespace")
        list_metadata_formats.add_format(format)
        self.assertEqual(list_metadata_formats.find_format("prefix"), format)

    def test_find_format_empty_prefix(self):
        list_metadata_formats = ListMetadataFormatsType()
        self.assertIsNone(list_metadata_formats.find_format(""))

if __name__ == "__main__":
    unittest.main()
