from pymongo import MongoClient
from datetime import datetime
import unittest

class TaskManager:
    def __init__(self, db_name, collection_name):
        self.client = MongoClient('mongodb://localhost:27017/')
        self.db = self.client[db_name]
        self.collection = self.db[collection_name]

    def list_collections(self):
        return self.db.list_collection_names()

    def insert_task(self, task):
        return self.collection.insert_one(task)

    def insert_multiple_tasks(self, tasks):
        return self.collection.insert_many(tasks)

    def find_first_task(self):
        return self.collection.find_one()

    def find_incomplete_tasks_with_title(self, title):
        return self.collection.find({"completed": False, "title": {"$regex": title, "$options": "i"}}, {"title": 1})

    def create_text_index(self, field):
        self.collection.create_index([(field, "text")])

    def text_search(self, query):
        return self.collection.find({"$text": {"$search": query}})

class TestTaskManager(unittest.TestCase):
    def setUp(self):
        self.task_manager = TaskManager("python_course", "todos")

    def test_list_collections(self):
        collections = self.task_manager.list_collections()
        self.assertIn("todos", collections)

    def test_insert_task(self):
        task = {
            "title": "Learn Data Analysis",
            "completed": False,
            "dueDate": datetime(2023, 9, 1),
            "priority": 3
        }
        result = self.task_manager.insert_task(task)
        self.assertIsNotNone(result.inserted_id)

    def test_insert_multiple_tasks(self):
        tasks = [
            {"title": "Task 1", "completed": False},
            {"title": "Task 2", "completed": True, "dueDate": datetime(2023, 9, 1)},
            {"title": "Task 3", "completed": False, "priority": 2}
        ]
        result = self.task_manager.insert_multiple_tasks(tasks)
        self.assertEqual(len(result.inserted_ids), len(tasks))

    def test_find_first_task(self):
        task = self.task_manager.find_first_task()
        self.assertIsNotNone(task)

    def test_find_incomplete_tasks_with_title(self):
        tasks = self.task_manager.find_incomplete_tasks_with_title("learn")
        for task in tasks:
            self.assertIn("title", task)
            self.assertFalse(task["completed"])

    def test_create_text_index(self):
        self.task_manager.create_text_index("title")
        self.assertIn("title_text", self.task_manager.collection.index_information())

    def test_text_search(self):
        results = self.task_manager.text_search("python")
        for result in results:
            self.assertIn("title", result)

if __name__ == "__main__":
