```python
# views.py
from django.shortcuts import render, get_object_or_404, redirect
from django.views import View
from django.views.generic import ListView, DetailView, CreateView, UpdateView
from .models import Recipe, MealPlan, MealPlanRecipe
from .forms import RecipeForm, MealPlanForm
from django.contrib.auth.mixins import LoginRequiredMixin
from django.contrib import messages

class HomePageView(View):
    def get(self, request):
        recipes = Recipe.objects.all().order_by('?')[:5]
        return render(request, 'home.html', {'recipes': recipes})

class DashboardView(LoginRequiredMixin, View):
    def get(self, request):
        total_recipes = Recipe.objects.count()
        total_meal_plans = MealPlan.objects.count()
        recent_plan = MealPlan.objects.filter(user=request.user).latest('created_at')
        return render(request, 'dashboard.html', {
            'total_recipes': total_recipes,
            'total_meal_plans': total_meal_plans,
            'recent_plan': recent_plan
        })

class RecipeListView(ListView):
    model = Recipe
    template_name = 'recipes.html'
    paginate_by = 10

    def get_queryset(self):
        return Recipe.objects.all().order_by('-votes', '-created_at')

class MealPlanListView(ListView):
    model = MealPlan
    template_name = 'meal_plans.html'
    paginate_by = 10

    def get_queryset(self):
        return MealPlan.objects.all().order_by('name')

class RecipeCreateView(LoginRequiredMixin, CreateView):
    model = Recipe
    form_class = RecipeForm
    template_name = 'recipe_form.html'

    def form_valid(self, form):
        form.save()
        messages.success(self.request, 'Recipe created successfully')
        return redirect('recipes')

class RecipeUpdateView(LoginRequiredMixin, UpdateView):
    model = Recipe
    form_class = RecipeForm
    template_name = 'recipe_form.html'

    def form_valid(self, form):
        form.save()
        messages.success(self.request, 'Recipe updated successfully')
        return redirect('recipes')

class MealPlanCreateView(LoginRequiredMixin, CreateView):
    model = MealPlan
    form_class = MealPlanForm
    template_name = 'meal_plan_form.html'

    def form_valid(self, form):
        form.instance.user = self.request.user
        form.save()
        messages.success(self.request, 'Meal plan created successfully')
        return redirect('meal_plans')

class MealPlanDetailView(DetailView):
    model = MealPlan
    template_name = 'meal_plan_detail.html'

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context['recipes'] = MealPlanRecipe.objects.filter(meal_plan=self.object)
        return context

class RecipeDetailView(DetailView):
    model = Recipe
    template_name = 'recipe_detail.html'

class RecipeVoteView(LoginRequiredMixin, View):
    def post(self, request, pk):
        recipe = get_object_or_404(Recipe, pk=pk)
        recipe.votes += 1
        recipe.save()
        return redirect('recipe_detail', pk=pk)

class AddRecipeToMealPlanView(LoginRequiredMixin, View):
    def post(self, request, meal_plan_pk, recipe_pk):
        meal_plan = get_object_or_404(MealPlan, pk=meal_plan_pk)
        recipe = get_object_or_404(Recipe, pk=recipe_pk)
        day = int(request.POST.get('day'))
        meal_number = int(request.POST.get('meal_number'))
        MealPlanRecipe.objects.create(meal_plan=meal_plan, recipe=recipe, day=day, meal_number=meal_number)
        return redirect('meal_plan_detail', pk=meal_plan_pk)
