import pytest
from unittest import mock

# Define the EnvCheck class with check methods for different tools
class EnvCheck:
    @staticmethod
    def CmdCheck():
        # Simulate checking for a command-line tool
        return True

    @staticmethod
    def AAPTCheck():
        # Simulate checking for the Android Asset Packaging Tool (AAPT)
        return True

    @staticmethod
    def ZIPALIGNCheck():
        # Simulate checking for the zipalign tool
        return True

# Define the pre_check function that uses the EnvCheck methods
def pre_check():
    if not EnvCheck.CmdCheck():
        raise SystemExit("CmdCheck failed.")
    if not EnvCheck.AAPTCheck():
        raise SystemExit("AAPTCheck failed.")
    if not EnvCheck.ZIPALIGNCheck():
        raise SystemExit("ZIPALIGNCheck failed.")
    print("All checks passed.")

# Test cases for the pre_check function
class TestPreCheck:
    @mock.patch.object(EnvCheck, 'CmdCheck', return_value=True)
    @mock.patch.object(EnvCheck, 'AAPTCheck', return_value=True)
    @mock.patch.object(EnvCheck, 'ZIPALIGNCheck', return_value=True)
    def test_all_passed(self, mock_zipalign, mock_aapt, mock_cmd):
        pre_check()

    @mock.patch.object(EnvCheck, 'CmdCheck', return_value=True)
    @mock.patch.object(EnvCheck, 'AAPTCheck', return_value=True)
    @mock.patch.object(EnvCheck, 'ZIPALIGNCheck', return_value=False)
    def test_failed(self, mock_zipalign, mock_aapt, mock_cmd):
        with pytest.raises(SystemExit) as e:
            pre_check()
        assert str(e.value) == "ZIPALIGNCheck failed."

# Run the test cases
if __name__ == "__main__":
    pytest.main()
```

