import os
from django.conf import settings

def configure_django_settings(config):
    # Debug
    if 'debug' in config:
        settings.DEBUG = config['debug']
        settings.TEMPLATE_DEBUG = config['debug']

    # Admins
    if 'admins' in config:
        if not all(isinstance(admin, tuple) for admin in config['admins']):
            raise ValueError("Admins must be a list of tuples")
        settings.ADMINS = config['admins']

    # Databases
    if 'databases' in config:
        if 'default' not in config['databases']:
            raise KeyError("Databases configuration must contain 'default' key")
        settings.DATABASES = config['databases']

    # Time zone
    if 'time_zone' in config:
        settings.TIME_ZONE = config['time_zone']

    # Language code
    if 'language_code' in config:
        settings.LANGUAGE_CODE = config['language_code']

    # Internationalization and localization
    if 'use_i18n' in config:
        settings.USE_I18N = config['use_i18n']
    if 'use_l10n' in config:
        settings.USE_L10N = config['use_l10n']
    if 'use_tz' in config:
        settings.USE_TZ = config['use_tz']

    # Media and static files
    if 'media_root' in config:
        if not os.path.isabs(config['media_root']):
            raise ValueError("Media root must be an absolute path")
        settings.MEDIA_ROOT = config['media_root']
    if 'media_url' in config:
        settings.MEDIA_URL = config['media_url']
    if 'static_root' in config:
        if not os.path.isabs(config['static_root']):
            raise ValueError("Static root must be an absolute path")
        settings.STATIC_ROOT = config['static_root']
    if 'static_url' in config:
        settings.STATIC_URL = config['static_url']
    if 'staticfiles_dirs' in config:
        settings.STATICFILES_DIRS = config['staticfiles_dirs']

    # Secret key
    if 'secret_key' in config:
        if not isinstance(config['secret_key'], str) or not config['secret_key']:
            raise ValueError("Secret key must be a non-empty string")
        settings.SECRET_KEY = config['secret_key']
```
