    def info(self, message, end="\n"):
        if self.level == "INFO" or self.level == "WARNING" or self.level == "ERROR":
            print(f"{self.name} - INFO: {message}", end=end)

    def warning(self, message, end="\n"):
        if self.level == "WARNING" or self.level == "ERROR":
            print(f"{self.name} - WARNING: {message}", end=end)

    def error(self, message, end="\n"):
        if self.level == "ERROR":
            print(f"{self.name} - ERROR: {message}", end=end)


class Flopi:
    def __init__(self):
        self.loggers = {"default": FlopiLogger("default", "INFO")}

    def set_logging_level_for(self, logger_name="default", level=None):
        if level not in ["INFO", "WARNING", "ERROR"]:
            raise ValueError("Invalid logging level")
        if logger_name not in self.loggers:
            self.loggers[logger_name] = FlopiLogger(logger_name, level)
        else:
            self.loggers[logger_name].level = level

    def get_logger(self, logger_name="default"):
        if logger_name not in self.loggers:
            self.loggers[logger_name] = FlopiLogger(logger_name, "INFO")
        return self.loggers[logger_name]


# Unit tests
class TestFlopiLogger(unittest.TestCase):
    def setUp(self):
        self.flopi = Flopi()
        self.logger = self.flopi.get_logger()

    def test_info(self):
        captured_output = StringIO()
        sys.stdout = captured_output
        self.logger.info("Test info message")
        sys.stdout = sys.__stdout__
        self.assertIn("INFO: Test info message", captured_output.getvalue())

    def test_warning(self):
        captured_output = StringIO()
        sys.stdout = captured_output
        self.logger.warning("Test warning message")
        sys.stdout = sys.__stdout__
        self.assertIn("WARNING: Test warning message", captured_output.getvalue())

    def test_error(self):
        captured_output = StringIO()
        sys.stdout = captured_output
        self.logger.error("Test error message")
        sys.stdout = sys.__stdout__
        self.assertIn("ERROR: Test error message", captured_output.getvalue())

    def test_set_logging_level(self):
        self.flopi.set_logging_level_for(level="WARNING")
        captured_output = StringIO()
        sys.stdout = captured_output
        self.logger.info("Test info message")
        self.logger.warning("Test warning message")
        sys.stdout = sys.__stdout__
        self.assertNotIn("INFO: Test info message", captured_output.getvalue())
        self.assertIn("WARNING: Test warning message", captured_output.getvalue())

    def test_invalid_logging_level(self):
        with self.assertRaises(ValueError):
            self.flopi.set_logging_level_for(level="DEBUG")

    def test_get_logger(self):
        logger = self.flopi.get_logger("test_logger")
        self.assertIsInstance(logger, FlopiLogger)
        self.assertEqual(logger.name, "test_logger")

    def test_default_logger(self):
        default_logger = self.flopi.get_logger()
        self.assertIsInstance(default_logger, FlopiLogger)
        self.assertEqual(default_logger.name, "default")


if __name__ == "__main__":
    unittest.main()
