import re
from datetime import datetime

class DomainValidator:
    def __init__(self):
        self.months = {
            'jan': 'Jan', 'feb': 'Feb', 'mar': 'Mar', 'apr': 'Apr', 'may': 'May', 'jun': 'Jun',
            'jul': 'Jul', 'aug': 'Aug', 'sep': 'Sep', 'oct': 'Oct', 'nov': 'Nov', 'dec': 'Dec'
        }

    def is_valid_domain(self, domain):
        pattern = r'^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z]{2,})+$'
        if re.match(pattern, domain):
            return f"{domain} is a valid domain name."
        else:
            return f"{domain} is not a valid domain name."

    def is_valid_ip(self, ip):
        pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
        if re.match(pattern, ip):
            return f"{ip} is a valid IP address."
        else:
            return f"{ip} is not a valid IP address."

    def convert_month(self, month):
        month = month.lower()
        if month in self.months:
            return self.months[month]
        else:
            return month

    def convert_to_two_digit(self, num):
        if len(num) == 1:
            return f"0{num}"
        else:
            return num

    def format_date(self, date_str):
        try:
            date = datetime.strptime(date_str, '%d-%b-%Y')
            return date.strftime('%d-%b-%Y')
        except ValueError:
            try:
                date = datetime.strptime(date_str, '%d-%B-%Y')
                return date.strftime('%d-%b-%Y')
            except ValueError:
                try:
                    date = datetime.strptime(date_str, '%d %b %Y')
                    return date.strftime('%d-%b-%Y')
                except ValueError:
                    try:
                        date = datetime.strptime(date_str, '%d %B %Y')
                        return date.strftime('%d-%b-%Y')
                    except ValueError:
                        try:
                            date = datetime.strptime(date_str, '%b %d %Y')
                            return date.strftime('%d-%b-%Y')
                        except ValueError:
                            try:
                                date = datetime.strptime(date_str, '%B %d %Y')
                                return date.strftime('%d-%b-%Y')
                            except ValueError:
                                return "Invalid date format."

# Unit tests
import unittest

class TestDomainValidator(unittest.TestCase):
    def setUp(self):
        self.validator = DomainValidator()

    def test_is_valid_domain(self):
        self.assertEqual(self.validator.is_valid_domain('example.com'), 'example.com is a valid domain name.')
        self.assertEqual(self.validator.is_valid_domain('invalid'), 'invalid is not a valid domain name.')

    def test_is_valid_ip(self):
        self.assertEqual(self.validator.is_valid_ip('192.168.1.1'), '192.168.1.1 is a valid IP address.')
        self.assertEqual(self.validator.is_valid_ip('256.1.1.1'), '256.1.1.1 is not a valid IP address.')

    def test_convert_month(self):
        self.assertEqual(self.validator.convert_month('Jan'), 'Jan')
        self.assertEqual(self.validator.convert_month('jan'), 'Jan')
        self.assertEqual(self.validator.convert_month('invalid'), 'invalid')

    def test_convert_to_two_digit(self):
        self.assertEqual(self.validator.convert_to_two_digit('1'), '01')
        self.assertEqual(self.validator.convert_to_two_digit('12'), '12')

    def test_format_date(self):
        self.assertEqual(self.validator.format_date('01-Jan-2022'), '01-Jan-2022')
        self.assertEqual(self.validator.format_date('1-Jan-2022'), '01-Jan-2022')
        self.assertEqual(self.validator.format_date('01 January 2022'), '01-Jan-2022')
        self.assertEqual(self.validator.format_date('January 01 2022'), '01-Jan-2022')
        self.assertEqual(self.validator.format_date('invalid'), 'Invalid date format.')

if __name__ == '__main__':
    unittest.main()
