import json
import sys
import unittest
from pathlib import Path

def process_functions(data):
    functions = []
    for item in data:
        if item['kind'] == 'function':
            function = {
                'name': item['name'],
                'signature': item['signature'],
                'doc': item['doc'],
                'params': item['params'],
                'template_args': item['template_args']
            }
            functions.append(function)
    return functions

def process_defines(data):
    defines = []
    for item in data:
        if item['kind'] == 'define':
            define = {
                'name': item['name'],
                'value': item['value'],
                'doc': item['doc']
            }
            defines.append(define)
    return defines

def process_typedefs(data):
    typedefs = []
    for item in data:
        if item['kind'] == 'typedef':
            typedef = {
                'name': item['name'],
                'value': item['value'],
                'doc': item['doc']
            }
            typedefs.append(typedef)
    return typedefs

def process_enumerations(data):
    enumerations = []
    for item in data:
        if item['kind'] == 'enumeration':
            enumeration = {
                'name': item['name'],
                'doc': item['doc']
            }
            enumerations.append(enumeration)
    return enumerations

def process_enum_members(data):
    enum_members = []
    for item in data:
        if item['kind'] == 'enum_member':
            enum_member = {
                'name': item['name'],
                'value': item['value'],
                'doc': item['doc']
            }
            enum_members.append(enum_member)
    return enum_members

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <source> <target-directory>")
        sys.exit(1)

    source = sys.argv[1]
    target_directory = sys.argv[2]

    with open(source, 'r') as f:
        data = [json.loads(line) for line in f]

    functions = process_functions(data)
    defines = process_defines(data)
    typedefs = process_typedefs(data)
    enumerations = process_enumerations(data)
    enum_members = process_enum_members(data)

    target_directory = Path(target_directory)
    target_directory.mkdir(parents=True, exist_ok=True)

    with open(target_directory / 'functions.json', 'w') as f:
        json.dump(functions, f, indent=4)

    with open(target_directory / 'defines.json', 'w') as f:
        json.dump(defines, f, indent=4)

    with open(target_directory / 'typedefs.json', 'w') as f:
        json.dump(typedefs, f, indent=4)

    with open(target_directory / 'enumerations.json', 'w') as f:
        json.dump(enumerations, f, indent=4)

    with open(target_directory / 'enum_members.json', 'w') as f:
        json.dump(enum_members, f, indent=4)

class TestDataExtraction(unittest.TestCase):
