import os
import time

class DirectoryTraversal:
    def __init__(self, root_dir):
        self.root_dir = root_dir

    def traverse(self):
        start_time = time.time()
        self._traverse_recursive(self.root_dir)
        end_time = time.time()
        total_time = end_time - start_time
        print(f"Total time taken: {total_time:.2f} seconds")

    def _traverse_recursive(self, current_dir):
        try:
            for entry in os.listdir(current_dir):
                entry_path = os.path.join(current_dir, entry)
                if os.path.isfile(entry_path):
                    print(entry_path)
                elif os.path.isdir(entry_path):
                    self._traverse_recursive(entry_path)
        except PermissionError:
            print(f"Permission denied: {current_dir}")
        except OSError as e:
            print(f"Error: {e}")

def main():
    root_dir = input("Enter the root directory path: ")
    if not os.path.exists(root_dir):
        print("Invalid root directory path")
        return

    traversal = DirectoryTraversal(root_dir)
    traversal.traverse()

if __name__ == "__main__":
    main()
