# Import necessary libraries
from flask import Flask, render_template, request
from flask_socketio import SocketIO, emit
import threading

# Initialize the Flask app and Socket.IO
app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'
socketio = SocketIO(app)

# Initialize the vote totals dictionary
vote_totals = {'yes': 0, 'no': 0, 'maybe': 0}

# Lock for thread-safe updates
lock = threading.Lock()

# Route to serve the HTML page
@app.route('/')
def index():
    return render_template('index.html', vote_totals=vote_totals)

# Socket.IO event handler for "submit vote" events
@socketio.on('submit vote')
def handle_submit_vote(data):
    # Validate user input
    if data['vote'] not in ['yes', 'no', 'maybe']:
        emit('error', {'message': 'Invalid vote selection'})
        return

    # Update the vote totals in a thread-safe manner
    with lock:
        vote_totals[data['vote']] += 1

    # Emit the updated vote totals to all connected clients
    emit('update vote totals', vote_totals, broadcast=True)

    # Provide clear visual feedback to the user
    emit('vote recorded', {'message': 'Your vote has been successfully recorded'})

# Run the Socket.IO server
if __name__ == '__main__':
    socketio.run(app)

