```python
from typing import List, Dict

class Audit:
    """Represents an audit with an ID and a list of related assessments."""
    def __init__(self, audit_id: int):
        self.audit_id = audit_id
        self.assessments: List[Assessment] = []
        self.archived = False

class Assessment:
    """Represents an assessment with an ID and a list of related evidence."""
    def __init__(self, assessment_id: int):
        self.assessment_id = assessment_id
        self.evidence: List[Evidence] = []
        self.archived = False

class Evidence:
    """Represents evidence with an ID."""
    def __init__(self, evidence_id: int):
        self.evidence_id = evidence_id
        self.archived = False

class ArchivingSystem:
    """Simulates an archiving system for audits, assessments, and evidence."""
    def __init__(self):
        self.audits: Dict[int, Audit] = {}
        self.assessments: Dict[int, Assessment] = {}
        self.evidence: Dict[int, Evidence] = {}

    def add_audit(self, audit_id: int):
        """Adds an audit to the system."""
        self.audits[audit_id] = Audit(audit_id)

    def add_assessment(self, assessment_id: int, audit_id: int):
        """Adds an assessment to the system and links it to an audit."""
        if audit_id not in self.audits:
            raise ValueError("Audit not found")
        self.assessments[assessment_id] = Assessment(assessment_id)
        self.audits[audit_id].assessments.append(self.assessments[assessment_id])

    def add_evidence(self, evidence_id: int, assessment_id: int):
        """Adds evidence to the system and links it to an assessment."""
        if assessment_id not in self.assessments:
            raise ValueError("Assessment not found")
        self.evidence[evidence_id] = Evidence(evidence_id)
        self.assessments[assessment_id].evidence.append(self.evidence[evidence_id])

    def archive_audit(self, audit_id: int) -> str:
        """Archives an audit and all related assessments and evidence."""
        if audit_id not in self.audits:
            return f"Audit {audit_id} not found"

        try:
            self.audits[audit_id].archived = True
            for assessment in self.audits[audit_id].assessments:
                assessment.archived = True
                for evidence in assessment.evidence:
                    evidence.archived = True
            return f"Audit {audit_id} archived successfully"
        except Exception as e:
            # Rollback in case of an error
            self.audits[audit_id].archived = False
            for assessment in self.audits[audit_id].assessments:
                assessment.archived = False
                for evidence in assessment.evidence:
                    evidence.archived = False
            return f"Error archiving audit {audit_id}: {str(e)}"

    def query_archived(self, item_type: str) -> List[int]:
        """Queries the system for archived items of a specific type."""
        if not isinstance(item_type, str):
            return ["Error: Invalid input type. Please enter a string."]

        if item_type.lower() == "audit":
            return [audit_id for audit_id, audit in self.audits.items() if audit.archived]
        elif item_type.lower() == "assessment":
            return [assessment_id for assessment_id, assessment in self.assessments.items() if assessment.archived]
        elif item_type.lower() == "evidence":
            return [evidence_id for evidence_id, evidence in self.evidence.items() if evidence.archived]
        else:
            return [f"Error: Invalid item type '{item_type}'. Please enter 'audit', 'assessment', or 'evidence'."]

import unittest

class TestArchivingSystem(unittest.TestCase):
    def test_archive_audit(self):
        system = ArchivingSystem()
        system.add_audit(1)
        system.add_assessment(1, 1)
        system.add_evidence(1, 1)
        self.assertEqual(system.archive_audit(1), "Audit 1 archived successfully")
        self.assertTrue(system.audits[1].archived)
        self.assertTrue(system.assessments[1].archived)
        self.assertTrue(system.evidence[1].archived)

    def test_archive_non_existent_audit(self):
        system = ArchivingSystem()
        self.assertEqual(system.archive_audit(1), "Audit 1 not found")

    def test_query_archived_audits(self):
        system = ArchivingSystem()
        system.add_audit(1)
        system.add_audit(2)
        system.archive_audit(1)
        self.assertEqual(system.query_archived("audit"), [1])

    def test_query_archived_assessments(self):
        system = ArchivingSystem()
        system.add_audit(1)
        system.add_assessment(1, 1)
        system.add_assessment(2, 1)
        system.archive_audit(1)
        self.assertEqual(system.query_archived("assessment"), [1, 2])

    def test_query_archived_evidence(self):
        system = ArchivingSystem()
        system.add_audit(1)
        system.add_assessment(1, 1)
        system.add_evidence(1, 1)
        system.add_evidence(2, 1)
        system.archive_audit(1)
        self.assertEqual(system.query_archived("evidence"), [1, 2])

    def test_query_invalid_item_type(self):
        system = ArchivingSystem()
        self.assertEqual(system.query_archived("invalid"), [f"Error: Invalid item type 'invalid'. Please enter 'audit', 'assessment', or 'evidence'."])

    def test_query_invalid_input_type(self):
        system = ArchivingSystem()
        self.assertEqual(system.query_archived(123), ["Error: Invalid input type. Please enter a string."])

if __name__ == "__main__":
    unittest.main()
