```python
from abc import ABC, abstractmethod
from enum import Enum

class VehicleType(Enum):
    CAR = 1
    TRUCK = 2
    MOTORCYCLE = 3

class CustomerType(Enum):
    CUSTOMER = 1
    EMPLOYEE = 2

class Vehicle(ABC):
    def __init__(self, base_price, mileage, age, vehicle_type):
        if base_price < 0:
            raise ValueError("Base price cannot be negative")
        if mileage < 0:
            raise ValueError("Mileage cannot be negative")
        if age < 0:
            raise ValueError("Age cannot be negative")
        self.base_price = base_price
        self.mileage = mileage
        self.age = age
        self.vehicle_type = vehicle_type

    @abstractmethod
    def adjust_price(self):
        pass

class Car(Vehicle):
    def adjust_price(self):
        # Adjust base price based on mileage and age
        adjusted_price = self.base_price * (1 - self.mileage / 100000 - self.age / 10)
        return adjusted_price

class Truck(Vehicle):
    def adjust_price(self):
        # Adjust base price based on mileage and age
        adjusted_price = self.base_price * (1 - self.mileage / 150000 - self.age / 10)
        return adjusted_price

class Motorcycle(Vehicle):
    def adjust_price(self):
        # Adjust base price based on mileage and age
        adjusted_price = self.base_price * (1 - self.mileage / 50000 - self.age / 10)
        return adjusted_price

class Contract(ABC):
    def __init__(self, vehicle, customer_type, lease_length=0, num_payments=0):
        self.vehicle = vehicle
        self.customer_type = customer_type
        self.lease_length = lease_length
        self.num_payments = num_payments

    @abstractmethod
    def total_value(self):
        pass

    @abstractmethod
    def monthly_value(self):
        pass

class BuyContract(Contract):
    def __init__(self, vehicle, customer_type, num_payments):
        super().__init__(vehicle, customer_type, num_payments=num_payments)
        if num_payments <= 0:
            raise ValueError("Number of payments must be positive")

    def total_value(self):
        adjusted_price = self.vehicle.adjust_price()
        if self.customer_type == CustomerType.EMPLOYEE:
            adjusted_price *= 0.9  # Apply 10% discount for employees
        tax_rate = 0.07
        total_value = adjusted_price * (1 + tax_rate)
        return total_value

    def monthly_value(self):
        total_value = self.total_value()
        monthly_value = total_value / self.num_payments
        return monthly_value

class LeaseContract(Contract):
    def __init__(self, vehicle, customer_type, lease_length):
        super().__init__(vehicle, customer_type, lease_length=lease_length)
        if lease_length <= 0:
            raise ValueError("Lease length must be positive")

    def total_value(self):
        adjusted_price = self.vehicle.adjust_price()
        lease_multiplier = {
            VehicleType.CAR: 1.2,
            VehicleType.TRUCK: 1.7,
            VehicleType.MOTORCYCLE: 1.1
        }
        total_value = adjusted_price * lease_multiplier[self.vehicle.vehicle_type] * self.lease_length
        return total_value

    def monthly_value(self):
        total_value = self.total_value()
        monthly_value = total_value / self.lease_length
        return monthly_value

# Test cases
car = Car(20000, 50000, 5, VehicleType.CAR)
truck = Truck(30000, 100000, 5, VehicleType.TRUCK)
motorcycle = Motorcycle(10000, 20000, 5, VehicleType.MOTORCYCLE)

buy_contract_car = BuyContract(car, CustomerType.CUSTOMER, 60)
buy_contract_truck = BuyContract(truck, CustomerType.CUSTOMER, 60)
buy_contract_motorcycle = BuyContract(motorcycle, CustomerType.CUSTOMER, 60)

lease_contract_car = LeaseContract(car, CustomerType.CUSTOMER, 36)
lease_contract_truck = LeaseContract(truck, CustomerType.CUSTOMER, 36)
lease_contract_motorcycle = LeaseContract(motorcycle, CustomerType.CUSTOMER, 36)

print("Buy Contract - Car: Total Value = {:.2f}, Monthly Value = {:.2f}".format(buy_contract_car.total_value(), buy_contract_car.monthly_value()))
print("Buy Contract - Truck: Total Value = {:.2f}, Monthly Value = {:.2f}".format(buy_contract_truck.total_value(), buy_contract_truck.monthly_value()))
print("Buy Contract - Motorcycle: Total Value = {:.2f}, Monthly Value = {:.2f}".format(buy_contract_motorcycle.total_value(), buy_contract_motorcycle.monthly_value()))

print("Lease Contract - Car: Total Value = {:.2f}, Monthly Value = {:.2f}".format(lease_contract_car.total_value(), lease_contract_car.monthly_value()))
print("Lease Contract - Truck: Total Value = {:.2f}, Monthly Value = {:.2f}".format(lease_contract_truck.total_value(), lease_contract_truck.monthly_value()))
print("Lease Contract - Motorcycle: Total Value = {:.2f}, Monthly Value = {:.2f}".format(lease_contract_motorcycle.total_value(), lease_contract_motorcycle.monthly_value()))

# Test employee discount
buy_contract_car_employee = BuyContract(car, CustomerType.EMPLOYEE, 60)
print("Buy Contract - Car (Employee): Total Value = {:.2f}, Monthly Value = {:.2f}".format(buy_contract_car_employee.total_value(), buy_contract_car_employee.monthly_value()))
