        if option == "title":
            return [album for album in self.albums if album["title"].lower() == value.lower()]
        elif option == "artist":
            return [album for album in self.albums if album["artist"].lower() == value.lower()]
        elif option == "year":
            return [album for album in self.albums if album["year"] == int(value)]
        elif option == "genre":
            return [album for album in self.albums if album["genre"].lower() == value.lower()]
        else:
