import ast
import fractions
import diofant as sp
import unicodedata
import keyword

class CodeTransformer(ast.NodeTransformer):
    def __init__(self, namespace):
        self.namespace = namespace

    def visit_BinOp(self, node):
        if isinstance(node.op, ast.Div) and isinstance(node.left, ast.Num) and isinstance(node.right, ast.Num):
            # Apply integer division transformation
            return ast.Call(
                func=ast.Name(id='fractions.Fraction', ctx=ast.Load()),
                args=[node.left, node.right],
                keywords=[]
            )
        return self.generic_visit(node)

    def visit_Name(self, node):
        if node.id not in self.namespace and not keyword.iskeyword(node.id):
            # Apply automatic symbol definition
            return ast.Call(
                func=ast.Attribute(
                    value=ast.Name(id='diofant', ctx=ast.Load()),
                    attr='symbol',
                    ctx=ast.Load()
                ),
                args=[ast.Str(s=node.id)],
                keywords=[]
            )
        return self.generic_visit(node)

    def visit_Num(self, node):
        if isinstance(node.n, float):
            # Apply float rationalization
            return ast.Call(
                func=ast.Name(id='fractions.Fraction', ctx=ast.Load()),
                args=[ast.Str(s=str(node.n))],
                keywords=[]
            )
        return self.generic_visit(node)

    def visit_FunctionDef(self, node):
        # Apply unicode identifiers normalization
        node.name = self.normalize_unicode(node.name)
        for arg in node.args.args:
            arg.arg = self.normalize_unicode(arg.arg)
        return self.generic_visit(node)

    def visit_ClassDef(self, node):
        # Apply unicode identifiers normalization
        node.name = self.normalize_unicode(node.name)
        return self.generic_visit(node)

    @staticmethod
    def normalize_unicode(name):
        return unicodedata.normalize('NFKD', name).encode('ascii', 'ignore').decode('utf-8')

def transform_code(code, namespace):
    tree = ast.parse(code)
    transformer = CodeTransformer(namespace)
    transformed_tree = transformer.visit(tree)
    return ast.unparse(transformed_tree)

# Example usage:
code = """
x = 1 / 2
y = 3.14
z = x + y
"""
namespace = {}
transformed_code = transform_code(code, namespace)
print(transformed_code)
