```python
import sys
import os

def add_task(task_description):
    """Adds a new task with the given description to the To-Do list."""
    with open('todo.txt', 'a') as f:
        f.write(f'[ ] {task_description}\n')

def list_tasks():
    """Lists all the tasks in the To-Do list with their status (done or not done)."""
    try:
        with open('todo.txt', 'r') as f:
            tasks = f.readlines()
            for i, task in enumerate(tasks, start=1):
                print(f'{i}. {task.strip()}')
    except FileNotFoundError:
        print('No tasks available.')

def mark_task_as_done(task_number):
    """Marks the task with the given task number as done."""
    try:
        with open('todo.txt', 'r') as f:
            tasks = f.readlines()
            if task_number > 0 and task_number <= len(tasks):
                tasks[task_number - 1] = tasks[task_number - 1].replace('[ ]', '[x]')
                with open('todo.txt', 'w') as f:
                    f.writelines(tasks)
            else:
                print('Invalid task number.')
    except FileNotFoundError:
        print('No tasks available.')

def main():
    if len(sys.argv) == 1:
        print('Usage: python todo.py <command> [arguments]')
        print('Available commands:')
        print('  add "task description"  - Adds a new task with the given description')
        print('  list                   - Lists all the tasks in the To-Do list')
        print('  done task_number       - Marks the task with the given task number as done')
    elif sys.argv[1] == 'add':
        if len(sys.argv) != 3:
            print('Usage: python todo.py add "task description"')
        else:
            task_description = sys.argv[2]
            add_task(task_description)
            print(f'Task "{task_description}" added successfully.')
    elif sys.argv[1] == 'list':
        list_tasks()
    elif sys.argv[1] == 'done':
        if len(sys.argv) != 3:
            print('Usage: python todo.py done task_number')
        else:
            try:
                task_number = int(sys.argv[2])
                mark_task_as_done(task_number)
                print(f'Task {task_number} marked as done.')
            except ValueError:
                print('Invalid task number. Please enter a valid integer.')
    else:
        print('Invalid command. Available commands: add, list, done')

if __name__ == '__main__':
    if not os.path.exists('todo.txt'):
        open('todo.txt', 'w').close()
    main()
```
