**User Authentication and Authorization System**
=====================================================

### System Overview

The user authentication and authorization system integrates with a MongoDB database and Google OAuth2 for external authentication. It provides functionalities for local and external user authentication, token generation, permission checks, and real-time monitoring of MongoDB collections.

### System Components

*   **MongoDB Database**: Stores user and permission data.
*   **Google OAuth2**: Provides external authentication.
*   **Bcrypt**: Used for password verification.
*   **JWT**: Used for token generation.

### System Implementation

#### Dependencies

*   `mongodb`: For interacting with the MongoDB database.
*   `google-auth`: For Google OAuth2 authentication.
*   `bcrypt`: For password verification.
*   `jsonwebtoken`: For JWT token generation.
*   `mongoose`: For MongoDB schema management.

#### MongoDB Schema

```javascript
// user.model.js
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const userSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    password: { type: String, required: true },
    email: { type: String, required: true, unique: true },
    groups: [{ type: String, ref: 'Group' }]
});

userSchema.pre('save', async function(next) {
    if (this.isNew || this.isModified('password')) {
        this.password = await bcrypt.hash(this.password, 10);
    }
    next();
});

const User = mongoose.model('User', userSchema);

module.exports = User;
```

```javascript
// group.model.js
const mongoose = require('mongoose');

const groupSchema = new mongoose.Schema({
    name: { type: String, required: true, unique: true },
    permissions: [{ type: String, ref: 'Permission' }]
});

const Group = mongoose.model('Group', groupSchema);

module.exports = Group;
```

```javascript
// permission.model.js
const mongoose = require('mongoose');

const permissionSchema = new mongoose.Schema({
    name: { type: String, required: true, unique: true },
    pvname: { type: String, required: true }
});

const Permission = mongoose.model('Permission', permissionSchema);

module.exports = Permission;
```

#### Local User Authentication

```javascript
// auth.local.js
const bcrypt = require('bcrypt');
const User = require('./user.model');

async function authenticateLocal(username, password) {
    try {
        const user = await User.findOne({ username });
        if (!user) {
            throw new Error('User not found');
        }
        const isValidPassword = await bcrypt.compare(password, user.password);
        if (!isValidPassword) {
            throw new Error('Invalid password');
        }
        return user;
    } catch (error) {
        throw error;
    }
}

module.exports = authenticateLocal;
```

#### External User Authentication using Google OAuth2

```javascript
// auth.google.js
const { google } = require('googleapis');

async function authenticateGoogle(token) {
    try {
        const oauth2Client = new google.auth.OAuth2(
            process.env.GOOGLE_CLIENT_ID,
            process.env.GOOGLE_CLIENT_SECRET,
            process.env.GOOGLE_REDIRECT_URI
        );
        const ticket = await oauth2Client.verifyIdToken({
            idToken: token,
            audience: process.env.GOOGLE_CLIENT_ID
        });
        const userData = ticket.getPayload();
        return userData;
    } catch (error) {
        throw error;
    }
}

module.exports = authenticateGoogle;
```

#### Token Generation

```javascript
// token.js
const jwt = require('jsonwebtoken');

async function generateTokens(user) {
    try {
        const accessToken = jwt.sign(
            { userId: user._id, username: user.username },
            process.env.SECRET_KEY,
            { expiresIn: '1h' }
        );
        const refreshToken = jwt.sign(
            { userId: user._id, username: user.username },
            process.env.SECRET_KEY,
            { expiresIn: '30d' }
        );
        return { accessToken, refreshToken };
    } catch (error) {
        throw error;
    }
}

module.exports = generateTokens;
```

#### Real-time Monitoring of MongoDB Collections

```javascript
// monitor.js
const mongoose = require('mongoose');

async function monitorCollections() {
    try {
        const userCollection = mongoose.connection.collection('users');
        const permissionCollection = mongoose.connection.collection('permissions');
        userCollection.watch().on('change', (change) => {
            console.log('User collection changed:', change);
        });
        permissionCollection.watch().on('change', (change) => {
            console.log('Permission collection changed:', change);
        });
    } catch (error) {
        throw error;
    }
}

module.exports = monitorCollections;
```

#### Permission Checks

```javascript
// permission.js
const User = require('./user.model');
const Group = require('./group.model');
const Permission = require('./permission.model');

async function checkPermission(userId, pvname) {
    try {
        const user = await User.findById(userId);
        if (!user) {
            throw new Error('User not found');
        }
        const groups = await Group.find({ _id: { $in: user.groups } });
        const permissions = await Permission.find({ _id: { $in: groups.map((group) => group.permissions) } });
        const hasPermission = permissions.some((permission) => permission.pvname === pvname);
        return hasPermission;
    } catch (error) {
        throw error;
    }
}

module.exports = checkPermission;
```

#### Role Determination

```javascript
// role.js
const User = require('./user.model');
const Group = require('./group.model');

async function determineRole(userId) {
    try {
        const user = await User.findById(userId);
        if (!user) {
            throw new Error('User not found');
        }
        const groups = await Group.find({ _id: { $in: user.groups } });
        const role = groups.map((group) => group.name);
        return role;
    } catch (error) {
        throw error;
    }
}

module.exports = determineRole;
```

#### Authorization Checks

```javascript
// auth.js
const checkPermission = require('./permission');
const determineRole = require('./role');

async function authorize(userId, pvname) {
    try {
        const hasPermission = await checkPermission(userId, pvname);
        if (!hasPermission) {
            throw new Error('User does not have permission to access the resource');
        }
        const role = await determineRole(userId);
        if (role.includes('admin')) {
            return true;
        }
        return false;
    } catch (error) {
        throw error;
    }
}

module.exports = authorize;
```

#### Error Handling

```javascript
// error.js
class AuthenticationError extends Error {
    constructor(message) {
        super(message);
        this.name = 'AuthenticationError';
    }
}

class AuthorizationError extends Error {
    constructor(message) {
        super(message);
        this.name = 'AuthorizationError';
    }
}

module.exports = { AuthenticationError, AuthorizationError };
```

#### Unit Tests

```javascript
// auth.test.js
