```python
import unittest
from typing import List

# Base class Model
class Model:
    def __init__(self, name: str):
        self.name = name

# Class representing a vehicle model and its associated maintenance program
class FleetVehicleModel(Model):
    def __init__(self, name: str):
        super().__init__(name)
        self.program_id = None
        self.program = None

    # Method to assign a maintenance program to the vehicle model
    def assign_program(self, program: 'VmsProgram'):
        if not isinstance(program, VmsProgram):
            raise ValueError("Invalid program. Only VmsProgram instances can be assigned.")
        self.program_id = id(program)
        self.program = program

    # Method to retrieve the details of the associated maintenance program
    def get_program_details(self):
        if self.program:
            return {
                "name": self.program.name,
                "services": self.program.services,
                "inspections": self.program.inspections
            }
        else:
            return None

# Class representing a maintenance program
class VmsProgram:
    def __init__(self, name: str):
        self.name = name
        self.services: List[str] = []
        self.inspections: List[str] = []

    # Method to add a service to the program
    def add_service(self, service: str):
        self.services.append(service)

    # Method to add an inspection to the program
    def add_inspection(self, inspection: str):
        self.inspections.append(inspection)

class TestFleetVehicleModel(unittest.TestCase):

    def test_assign_program(self):
        vehicle_model = FleetVehicleModel("Test Model")
        program = VmsProgram("Test Program")
        vehicle_model.assign_program(program)
        self.assertEqual(vehicle_model.program_id, id(program))

    def test_assign_invalid_program(self):
        vehicle_model = FleetVehicleModel("Test Model")
        with self.assertRaises(ValueError):
            vehicle_model.assign_program("Invalid Program")

    def test_get_program_details(self):
        vehicle_model = FleetVehicleModel("Test Model")
        program = VmsProgram("Test Program")
        program.add_service("Service 1")
        program.add_inspection("Inspection 1")
        vehicle_model.assign_program(program)
        expected_details = {
            "name": "Test Program",
            "services": ["Service 1"],
            "inspections": ["Inspection 1"]
        }
        self.assertEqual(vehicle_model.get_program_details(), expected_details)

    def test_get_program_details_no_program(self):
        vehicle_model = FleetVehicleModel("Test Model")
        self.assertIsNone(vehicle_model.get_program_details())

class TestVmsProgram(unittest.TestCase):

    def test_add_service(self):
        program = VmsProgram("Test Program")
        program.add_service("Service 1")
        self.assertEqual(program.services, ["Service 1"])

    def test_add_inspection(self):
        program = VmsProgram("Test Program")
        program.add_inspection("Inspection 1")
        self.assertEqual(program.inspections, ["Inspection 1"])

if __name__ == '__main__':
    unittest.main()
```

