from abc import ABC, abstractmethod
import os

# Define an abstract base class for scan types
class ScanType(ABC):
    @abstractmethod
    def execute(self, file_path):
        pass

# Define the BinaryScan class
class BinaryScan(ScanType):
    def execute(self, file_path):
        return f"BinaryScan executed for file: {file_path}"

# Define the FileScan class
class FileScan(ScanType):
    def execute(self, file_path):
        return f"FileScan executed for file: {file_path}"

# Define the JsonScan class
class JsonScan(ScanType):
    def execute(self, file_path):
        return f"JsonScan executed for file: {file_path}"

# Define the ArrowScan class
class ArrowScan(ScanType):
    def execute(self, file_path):
        return f"ArrowScan executed for file: {file_path}"

# Define the DocScan class
class DocScan(ScanType):
    def execute(self, file_path):
        return f"DocScan executed for file: {file_path}"

# Define the MaterializedScan class
class MaterializedScan(ScanType):
    def execute(self, file_path):
        return f"MaterializedScan executed for file: {file_path}"

# Define the PandasScan class
class PandasScan(ScanType):
    def execute(self, file_path):
        return f"PandasScan executed for file: {file_path}"

# Define the ScanManager class
class ScanManager:
    def __init__(self):
        self.scan_types = {}

    def register_scan(self, scan_type, file_extensions):
        for extension in file_extensions:
            self.scan_types[extension] = scan_type

    def execute_scan(self, file_path):
        file_extension = os.path.splitext(file_path)[1][1:]  # Get the file extension without the dot
        if file_extension not in self.scan_types:
            raise ValueError(f"Unrecognized file extension: {file_extension}")
        scan_type = self.scan_types[file_extension]
        return scan_type().execute(file_path)

# Example usage
if __name__ == "__main__":
    scan_manager = ScanManager()

    # Register scan types
    scan_manager.register_scan(BinaryScan, ["bin"])
    scan_manager.register_scan(FileScan, ["txt"])
    scan_manager.register_scan(JsonScan, ["json"])
    scan_manager.register_scan(ArrowScan, ["arrow"])
    scan_manager.register_scan(DocScan, ["docx", "pdf"])
    scan_manager.register_scan(PandasScan, ["csv"])

    # Execute scans
    print(scan_manager.execute_scan("example.bin"))  # BinaryScan executed for file: example.bin
    print(scan_manager.execute_scan("example.txt"))  # FileScan executed for file: example.txt
    print(scan_manager.execute_scan("example.json"))  # JsonScan executed for file: example.json
    print(scan_manager.execute_scan("example.arrow"))  # ArrowScan executed for file: example.arrow
    print(scan_manager.execute_scan("example.docx"))  # DocScan executed for file: example.docx
    print(scan_manager.execute_scan("example.pdf"))  # DocScan executed for file: example.pdf
    print(scan_manager.execute_scan("example.csv"))  # PandasScan executed for file: example.csv

    # Try executing a scan with an unrecognized file extension
    try:
        print(scan_manager.execute_scan("example.mp3"))
    except ValueError as e:
        print(e)  # Unrecognized file extension: mp3
