tree.add_leaf('b2', 'orange')

# Searching for leaves
print(tree.find_leaf('apple').id)  # Should print 'b1'
print(tree.find_leaf('orange').id)  # Should print 'b2'
print(tree.find_leaf('banana'))  # Should print None
