        if 'pool_size' not in layer_dict or 'stride' not in layer_dict:
            raise ValueError("Missing required parameters")
        return cls(layer_dict['pool_size'], layer_dict['stride'])

    def get_output_shape(self, input_shape):
        # Calculate output shape based on input shape and pooling parameters
        output_height = (input_shape[0] - self.pool_size) // self.stride + 1
        output_width = (input_shape[1] - self.pool_size) // self.stride + 1
        return (output_height, output_width, input_shape[2])

    def get_output_size(self, input_shape):
        output_shape = self.get_output_shape(input_shape)
        return output_shape[0] * output_shape[1] * output_shape[2]

class FullConnection(Layer):
    def __init__(self, num_units):
        self.num_units = num_units

    def to_dict(self):
        return {
            'type': 'FullConnection',
            'num_units': self.num_units
        }

    @classmethod
    def from_dict(cls, layer_dict):
        if 'type' not in layer_dict or layer_dict['type'] != 'FullConnection':
            raise ValueError("Invalid layer type")
        if 'num_units' not in layer_dict:
            raise ValueError("Missing required parameters")
        return cls(layer_dict['num_units'])

    def get_output_shape(self):
        return (self.num_units,)

    def get_output_size(self):
        return self.num_units

def from_dict(layer_dict):
    layer_type = layer_dict['type']
    if layer_type == 'Input':
        return Input.from_dict(layer_dict)
    elif layer_type == 'Convolution':
        return Convolution.from_dict(layer_dict)
    elif layer_type == 'Pooling':
        return Pooling.from_dict(layer_dict)
    elif layer_type == 'FullConnection':
        return FullConnection.from_dict(layer_dict)
    else:
        raise ValueError("Invalid layer type")

class TestLayerSerialization(unittest.TestCase):
    def test_input_layer(self):
        input_layer = Input((28, 28, 1))
