import os
import subprocess
import re

class LaTeXDocument:
    def __init__(self, filename, documentclass='article', options=None):
        self.filename = filename
        self.documentclass = documentclass
        self.options = options if options else []
        self.content = []
        self.metadata = {}

    def _escape_latex(self, text):
        """Escape LaTeX special characters in the given text."""
        return re.sub(r'([\\{}&%$#_~^|])', r'\\\1', text)

    def _add_command(self, command, *args):
        """Add a LaTeX command to the document content."""
        self.content.append(f'\\{command}{"{" + "}".join(map(self._escape_latex, args)) + "}')

    def _add_environment(self, environment, content):
        """Add a LaTeX environment to the document content."""
        self.content.append(f'\\begin{{{environment}}}')
        self.content.extend(map(self._escape_latex, content))
        self.content.append(f'\\end{{{environment}}}')

    def add_section(self, title, label=None):
        """Add a section with the given title and an optional label for referencing."""
        if not isinstance(title, str):
            raise TypeError("Title must be a string")
        self._add_command('section', title)
        if label:
            self._add_command('label', label)

    def add_subsection(self, title, label=None):
        """Add a subsection with the given title and an optional label for referencing."""
        if not isinstance(title, str):
            raise TypeError("Title must be a string")
        self._add_command('subsection', title)
        if label:
            self._add_command('label', label)

    def add_paragraph(self, text):
        """Add a paragraph with the given text."""
        if not isinstance(text, str):
            raise TypeError("Text must be a string")
        self.content.append(self._escape_latex(text))

    def add_bullet_points(self, items):
        """Add a bullet point list with the given items."""
        if not isinstance(items, list):
            raise TypeError("Items must be a list")
        self._add_environment('itemize', [f'\\item {self._escape_latex(item)}' for item in items])

    def add_equation(self, equation, label=None):
        """Add an equation with the given LaTeX code and an optional label for referencing."""
        if not isinstance(equation, str):
            raise TypeError("Equation must be a string")
        self._add_environment('equation', [equation])
        if label:
            self._add_command('label', label)

    def add_image(self, filepath, options=None):
        """Add an image with the given file path and optional LaTeX options for formatting."""
        if not isinstance(filepath, str):
            raise TypeError("Filepath must be a string")
        if options and not isinstance(options, str):
            raise TypeError("Options must be a string")
        self._add_command('includegraphics' + (f'[{options}]' if options else ''), filepath)

    def add_table(self, data, column_format, caption=None, label=None):
        """Add a table with the given data, column format, caption, and an optional label for referencing."""
        if not isinstance(data, list) or not all(isinstance(row, list) for row in data):
            raise TypeError("Data must be a list of lists")
        if not isinstance(column_format, str):
            raise TypeError("Column format must be a string")
        if caption and not isinstance(caption, str):
            raise TypeError("Caption must be a string")
        table_content = [f'\\begin{{{column_format}}}', '\\hline']
        for row in data:
            table_content.append(' & '.join(map(self._escape_latex, row)) + ' \\\\')
            table_content.append('\\hline')
        table_content.append('\\end{' + column_format + '}')
        self._add_environment('table', table_content)
        if caption:
            self._add_command('caption', caption)
        if label:
            self._add_command('label', label)

    def set_metadata(self, title=None, author=None, date=None):
        """Set the document's metadata."""
        if title:
            self.metadata['title'] = title
        if author:
            self.metadata['author'] = author
        if date:
            self.metadata['date'] = date

    def include_package(self, package, options=None):
        """Include a LaTeX package to enhance document functionality."""
        if not isinstance(package, str):
            raise TypeError("Package must be a string")
        if options and not isinstance(options, str):
            raise TypeError("Options must be a string")
        self.content.insert(0, f'\\usepackage{("[" + options + "]" if options else "")}{{{package}}}')

    def compile(self):
        """Compile the LaTeX document into a PDF."""
        with open(self.filename + '.tex', 'w') as f:
            f.write(f'\\documentclass{("[" + ",".join(self.options) + "]" if self.options else "")}{{{self.documentclass}}}\n')
            for key, value in self.metadata.items():
                f.write(f'\\{key}{{{value}}}\n')
            f.write('\\begin{document}\n')
            for line in self.content:
                f.write(line + '\n')
            f.write('\\end{document}\n')
        subprocess.run(['pdflatex', self.filename + '.tex'])
        os.remove(self.filename + '.aux')
        os.remove(self.filename + '.log')
        os.remove(self.filename + '.tex')

# Example usage:
document = LaTeXDocument('example')
document.set_metadata(title='Example Document', author='John Doe')
document.include_package('graphicx')
document.add_section('Introduction')
document.add_paragraph('This is an example document.')
document.add_bullet_points(['Item 1', 'Item 2', 'Item 3'])
document.add_equation('E=mc^2', label='eq:energy')
document.add_image('image.png', options='width=0.5\\textwidth')
document.add_table([['Column 1', 'Column 2'], ['Row 1, Column 1', 'Row 1, Column 2'], ['Row 2, Column 1', 'Row 2, Column 2']], 'cc', caption='Example Table', label='tab:example')
document.compile()
```

