                                    value = min(value, self.alpha_beta(depth-1, alpha, beta, True))
                                    self.board[i][j] = 'X'
                                    self.board[k][col] = '-'
                                    beta = min(beta, value)
                                    if beta <= alpha:
                                        break
            return value

