        best_value = -1000
        best_move = None
        for i in range(5):
            for j in range(5):
                if self.board[i][j] == 'O':
                    for k in range(5):
                        for col in range(5):
                            if self.board[k][col] == '-':
                                self.board[k][col] = 'O'
                                self.board[i][j] = '-'
                                value = self.alpha_beta(2, -1000, 1000, False)
                                self.board[i][j] = 'O'
                                self.board[k][col] = '-'
                                if value > best_value:
                                    best_value = value
                                    best_move = (i, j, k, col)
        if best_move:
            self.board[best_move[2]][best_move[3]] = 'O'
            self.board[best_move[0]][best_move[1]] = '-'
        else:
            print("No valid move found")

