import numpy as np

def calculate_determinant(n):
    """
    Calculate the determinant of a circular adjacency matrix representing a simple undirected cycle graph with n vertices.

    Args:
    n (int): The number of vertices in the cycle graph.

    Returns:
    int: The determinant of the circular adjacency matrix.
    """
    # Create the circular adjacency matrix
    A = np.zeros((n, n))
    for i in range(n):
        A[i, i] = 3
        A[i, (i + 1) % n] = -1
        A[(i + 1) % n, i] = -1

    # Calculate the determinant using Gaussian elimination without pivoting
    det = 1
    for i in range(n):
        # Check for zero pivot
        if A[i, i] == 0:
            raise ValueError("Zero pivot encountered during Gaussian elimination")

        # Update determinant
        det *= A[i, i]

        # Eliminate below pivot
        for j in range(i + 1, n):
            factor = A[j, i] / A[i, i]
            A[j, :] -= factor * A[i, :]

    # Calculate the determinant of the upper triangular matrix
    for i in range(n):
        det *= A[i, i]

    return int(det)

def main():
