import requests
from bs4 import BeautifulSoup
import json

# Constants
URL = "https://example.com/airfield-data"  # Replace with the actual URL
OUTPUT_FILE = "airfield_data.json"

# Helper functions
def title_case(s):
    return s.title()

def capitalize(s):
    return s.upper()

def split_coordinates(s):
    parts = s.split(", ")
    return {"lat": parts[0], "lon": parts[1]}

def split_runway_orientation(s):
    parts = s.split("/")
    return {"orientation1": parts[0], "orientation2": parts[1]}

def split_runway_position(s):
    parts = s.split("/")
    return {"threshold1": parts[0], "threshold2": parts[1]}

def split_runway_surface(s):
    parts = s.split("x")
    return {"length": int(parts[0]), "width": int(parts[1]), "surface": parts[2]}

# Main function
def scrape_airfield_data():
    response = requests.get(URL)
    soup = BeautifulSoup(response.content, "html.parser")
    table = soup.find("table")

    airfields = []
    for row in table.find_all("tr")[1:]:
        cols = row.find_all("td")
        airfield = {
            "code": cols[0].text.strip(),
            "name": title_case(cols[1].text.strip()),
            "magnetic_orientation": float(cols[2].text.strip()) if cols[2].text.strip() else None,
            "coordinates": split_coordinates(cols[3].text.strip()) if cols[3].text.strip() else None,
            "altitude": int(cols[4].text.strip()) if cols[4].text.strip() else None,
            "traffic": cols[5].text.strip() if cols[5].text.strip() else None,
            "ground_level": float(cols[6].text.strip()) if cols[6].text.strip() else None,
            "status": capitalize(cols[7].text.strip()) if cols[7].text.strip() else None,
            "runways": []
        }

        for i in range(8, len(cols), 5):
            runway = {
                "surface": split_runway_surface(cols[i].text.strip()) if cols[i].text.strip() else None,
                "orientation": split_runway_orientation(cols[i+1].text.strip()) if cols[i+1].text.strip() else None,
                "threshold_position": split_runway_position(cols[i+2].text.strip()) if cols[i+2].text.strip() else None,
                "altitude": int(cols[i+3].text.strip()) if cols[i+3].text.strip() else None
            }
            airfield["runways"].append(runway)

        airfields.append(airfield)

    with open(OUTPUT_FILE, "w") as f:
        json.dump(airfields, f, indent=4)

# Run the main function
scrape_airfield_data()
