import unittest

class Secure:
    def __init__(self, value: Union[str, Decimal, date, datetime], encryption_level: int, access_level: int):
        if not isinstance(value, (str, Decimal, date, datetime)):
            raise TypeError("Unsupported data type")
        self.value = self._encrypt(value, encryption_level)
        self.encryption_level = encryption_level
        self.access_level = access_level

    def _encrypt(self, value: Union[str, Decimal, date, datetime], encryption_level: int) -> str:
        if isinstance(value, str):
            return self._encrypt_string(value, encryption_level)
        elif isinstance(value, Decimal):
            return self._encrypt_string(str(value), encryption_level)
        elif isinstance(value, date):
            return self._encrypt_string(value.isoformat(), encryption_level)
        elif isinstance(value, datetime):
            return self._encrypt_string(value.isoformat(), encryption_level)

    def _encrypt_string(self, value: str, encryption_level: int) -> str:
        key = hashlib.sha256(str(encryption_level).encode()).digest()
        return base64.b64encode(hmac.new(key, value.encode(), hashlib.sha256).digest() + value.encode()).decode()

    def _decrypt(self, value: str, encryption_level: int) -> str:
        key = hashlib.sha256(str(encryption_level).encode()).digest()
