class Square:
    """
    A class representing a square by its size.

    Attributes:
    size (int): The side length of the square.

    Methods:
    area(): Returns the area of the square.
    """

    def __init__(self, size):
        # Check if size is an integer
        if not isinstance(size, int):
            raise TypeError('size must be an integer')

        # Check if size is not negative
        if size < 0:
            raise ValueError('size must be >= 0')

        # Set the private attribute _size
        self._size = size

    def area(self):
        # Calculate and return the area of the square
        return self._size ** 2

    def __lt__(self, other):
        # Compare the areas of two squares using the less than operator
        return self.area() < other.area()

    def __le__(self, other):
        # Compare the areas of two squares using the less than or equal to operator
        return self.area() <= other.area()

    def __eq__(self, other):
        # Compare the areas of two squares using the equal to operator
        return self.area() == other.area()

    def __ne__(self, other):
        # Compare the areas of two squares using the not equal to operator
        return self.area() != other.area()

    def __gt__(self, other):
        # Compare the areas of two squares using the greater than operator
        return self.area() > other.area()

    def __ge__(self, other):
        # Compare the areas of two squares using the greater than or equal to operator
        return self.area() >= other.area()


